actions.script:
const L = (text) => ec.l10n.localize(text)
const link = ec.service.sync().name('org.moqui.impl.EdgeServices.get#LinkStatus').call() || {}
const state = link.state || 'unpaired'
notBuilt = state === 'notBuilt'
notStarted = state === 'notStarted'
const running = !notBuilt && !notStarted
// an edge or all-in-one node takes links; the wizard is a local node's (plans/Edge-Node.md §10)
isEdge = running && ['edge', 'all-in-one'].includes(link.nodeRole)
paired = running && !isEdge && state !== 'unpaired'
unpaired = running && !isEdge && state === 'unpaired'
const states = {connecting: [L('Connecting'), 'info'], linked: [L('Linked'), 'positive'], retrying: [L('Retrying'), 'warning'],
    refused: [L('Refused'), 'negative']}
const [stateLabel, stateColor] = states[state] || [state, 'grey']
const list = (items) => Array.from(items || []).join(', ')
incompatibleMessage = paired && link.compatible === false ? link.message || '' : ''
lastError = link.lastError || ''
refusedState = paired && state === 'refused'
edge = {edgeName: link.edgeName || link.url || L('Edge node'), stateLabel, stateColor,
    url: link.url || '',
    generationText: link.generation ? String(link.generation) : '',
    rttText: link.rttMs != null ? ec.l10n.format(link.rttMs, '#,##0.0') + ' ms' : '',
    lastConnectText: link.lastConnectDate ? ec.l10n.format(link.lastConnectDate, '') : L('Not yet'),
    reconnectsText: String(link.reconnects ?? 0),
    fingerprint: link.fingerprint || '',
    versionText: link.binaryVersion ? link.binaryVersion + (link.linkVersion ? ' · ' + L('link') + ' ' + link.linkVersion : '') : '',
    publicNamesText: list(link.publicNames),
    featuresText: list(link.features)}
// the queue and replication (plans/Edge-Node.md §5.2): this node's own rows and state, with or without the
// link; a probe (Practices-App-Dev §4), so a failure shows on the page instead of failing it
let work = {}
queueError = ''
if (paired) {
    ec.message.pushErrors()
    try {
        work = ec.service.sync().name('org.moqui.impl.EdgeServices.get#QueueStatus').call() || {}
        if (ec.message.hasError()) queueError = ec.message.getErrorsString()
    } finally {
        ec.message.clearErrors()
        ec.message.popErrors()
    }
}
queuePaused = !!work.paused
const age = (seconds) => seconds == null ? '' : seconds < 120 ? seconds + ' s'
    : seconds < 7200 ? Math.round(seconds / 60) + ' min' : Math.round(seconds / 3600) + ' h'
// a local node's own items all go to the edge node
kindList = Array.from(work.kindList || []).filter((kind) => kind.directionEnumId === 'EqdToEdge')
    .map((kind) => ({kind: kind.kind, pendingText: String(kind.pending ?? 0),
        failedText: String(kind.failed ?? 0), oldestText: age(kind.oldestAgeSeconds)}))
setList = Array.from(work.setList || []).map((set) => ({setName: set.setName,
    epochText: set.epoch ? String(set.epoch).slice(0, 8) : '', ackedText: String(set.acked ?? 0),
    waitingText: String(set.waiting ?? 0),
    stateLabel: set.snapshotNeeded ? L('Full send due') : L('Up to date'),
    stateColor: set.snapshotNeeded ? 'warning' : 'positive',
    lastAckText: set.lastAckDate ? ec.l10n.format(set.lastAckDate, '') : L('Not yet')}))
// the areas set up (plans/Edge-Node.md §5.7): the host names from the edge node while the link is up, the
// rest from this node's own rows and settings
setup = {}
if (paired) {
    let hostsText = L('Not known while the link is down')
    let xmppText = hostsText
    // the edge node's SIP engine as its offer says it now (E10 phones): its trunks and the fallbacks it holds
    let sipOffer = null
    const xmppDomain = String(System.getProperty('xmpp_domain') || '').trim().replace(/\.$/, '').toLowerCase()
    if (state === 'linked') {
        ec.message.pushErrors()
        try {
            const offer = (ec.service.sync().name('org.moqui.impl.EdgeServices.get#EdgeOffer').call() || {}).offer || {}
            if (!ec.message.hasError()) {
                const names = Array.from(offer.nodeHosts || []).map((host) => host.hostName +
                    ' (' + (host.modeEnumId === 'EdgeHostTerminate' ? L('terminate') : L('passthrough')) + ')')
                hostsText = names.length ? names.join(', ') : L('None')
                sipOffer = offer.sip || null
                const xmpp = offer.xmpp || {}
                const ports = [xmpp.port, xmpp.tlsPort].filter((port) => port).join(', ')
                // through the edge node: its tunnel ports come here, and the domain is a host name of this node there
                const hosted = !!xmppDomain && Array.from(offer.nodeHosts || [])
                    .some((host) => String(host.hostName || '').replace(/\.$/, '').toLowerCase() === xmppDomain)
                xmppText = !xmppDomain ? L('No XMPP server on this node') : xmpp.needsNode ? L('Refused: set edge_xmpp_node on the edge node')
                    : xmpp.available && !xmpp.otherNode && hosted
                    ? ec.resource.expand('${domain} through ports ${ports}', '', {domain: xmppDomain, ports})
                    : L('Not through the edge node')
            }
        } finally {
            ec.message.clearErrors()
            ec.message.popErrors()
        }
    }
    // calls (E7, E10 calls): the edge node's media node row the link keeps, live, and this node's choice
    const callsOff = ['false', 'n', 'no', '0', 'off'].includes(String(System.getProperty('edge_calls_enabled') || '').trim().toLowerCase())
    const liveRows = Array.from(ec.entity.find('moqui.call.CallMediaNode')
        .condition('heartbeatDate', '>=', new Date(Date.now() - 60000)).useCache(false).disableAuthz().list())
    const liveRow = liveRows.find((row) => row.edgeLinked === 'Y')
    // off needs a media node of this node's own to take new calls (moqui_core::edge::calls::own_media_nodes)
    const ownLive = liveRows.some((row) => row.edgeLinked !== 'Y' && row.draining !== 'Y')
    const callsText = !link.mediaAddress ? L('The edge node runs no media node')
        : callsOff ? (ownLive ? L("Off: new calls use this node's own media nodes")
            : L('Off, and this node has no live media node of its own, so no new call can start'))
        : liveRow ? ec.resource.expand('New calls on the edge node at ${address}', '', {address: link.mediaAddress}) +
            (Array.from(link.turnUrls || []).length ? ', ' + L('with its TURN') : ', ' + L('no TURN'))
        : L('Not live: the link keeps the edge node as media node while it is up')
    // phones (E8, E10 phones): the edge node's SipNode row the link keeps, live, and this node's choice
    const sipOff = ['false', 'n', 'no', '0', 'off'].includes(String(System.getProperty('edge_sip_enabled') || '').trim().toLowerCase())
    const sipRow = Array.from(ec.entity.find('moqui.call.SipNode').condition('edgeLinked', 'Y')
        .condition('heartbeatDate', '>=', new Date(Date.now() - 60000)).useCache(false).disableAuthz().list())[0]
    const sipText = sipOff ? L('Off: the edge node gets no trunks or fallbacks, and its SIP engine takes no new call')
        : sipRow ? ec.resource.expand('Trunks and phones through the edge node at ${address}', '',
                {address: [sipRow.sipAddress, sipRow.tlsAddress].filter((address) => address).join(', ')}) +
            ', ' + (sipRow.registrarEnabled === 'Y' ? L('registrar on') : L('registrar off')) +
            (sipOffer ? ', ' + ec.resource.expand('${trunks} trunks loaded there, ${fallbacks} numbers with a fallback', '',
                {trunks: Array.from(sipOffer.trunks || []).length, fallbacks: sipOffer.fallbacks || 0}) : '')
        : L('Not live: the edge node runs no SIP engine, or the link is down')
    const system = ec.entity.find('moqui.basic.email.EmailServer').condition('emailServerId', 'SYSTEM').disableAuthz().one()
    const accounts = ec.entity.find('moqui.basic.email.EmailAccount').condition('emailServerId', 'EDGE').disableAuthz().count()
    const systemEdge = system?.smtpHost === 'edge:'
    const chatUrl = String(System.getProperty('channels_public_url') || '')
    const client = String(System.getProperty('pass_edge_client') || '') || 'edge'
    const sites = String(System.getProperty('pass_client_' + client + '_sites') || '')
    setup = {hostsText,
        mailText: systemEdge || accounts ? (systemEdge ? L('The system') + (accounts ? ', ' : '') : '') +
            (accounts ? ec.resource.expand('${n} accounts', '', {n: accounts}) : '') + ' ' + L('through the edge node') : L('Not through the edge node'),
        chatText: chatUrl ? chatUrl + '/channels/(bridge)/webhook' : L('Not set'),
        passText: sites ? ec.resource.expand('${sites}, as PASS client ${client}', '', {sites, client}) : L('Not set'),
        xmppText, callsText, sipText}
}
